CREATE TABLE `tbl_customer` (
  `cus_id` int NOT NULL AUTO_INCREMENT,
  `cus_name` varchar(100) DEFAULT NULL,
  `cus_email` varchar(100) DEFAULT NULL,
  `cus_gender` varchar(55) DEFAULT NULL,
  `date_of_birth` date DEFAULT '1000-01-01',
  `profile_image` varchar(255) DEFAULT NULL,
  `cus_password` varchar(255) DEFAULT NULL,
  `cus_mobile` varchar(14) DEFAULT NULL,
  `cus_mobile_country_code` int DEFAULT NULL,
  `cus_mobile_full_no` varchar(255) DEFAULT NULL,
  `cus_address` text,
  `cus_city` varchar(255) DEFAULT NULL,
  `cus_country` varchar(255) DEFAULT NULL,
  `cus_state` varchar(255) DEFAULT NULL,
  `cus_zip` varchar(55) DEFAULT NULL,
  `cus_otp` varchar(10) DEFAULT NULL,
  `credentials_sent` tinyint DEFAULT '0',
  `createdon` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedon` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted_on` datetime DEFAULT NULL,
  `createdby` int DEFAULT NULL,
  `updatedby` int DEFAULT NULL,
  `deleted_by` int DEFAULT NULL,
  `delete_status` tinyint NOT NULL DEFAULT '0',
  `status` tinyint NOT NULL DEFAULT '1',
  PRIMARY KEY (`cus_id`)
) ENGINE=MyISAM AUTO_INCREMENT=909 DEFAULT CHARSET=latin1;
