--
-- Table structure for table `tbl_order`
--

DROP TABLE IF EXISTS `tbl_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tbl_order` (
  `order_id` int NOT NULL AUTO_INCREMENT,
  `order_bussiness_code` varchar(100) DEFAULT NULL,
  `order_no` int DEFAULT NULL,
  `invoice_no` varchar(200) DEFAULT NULL,
  `dublicate_order_check` varchar(255) DEFAULT NULL,
  `cus_id` int DEFAULT NULL,
  `ship_id` int DEFAULT NULL,
  `bill_id` int DEFAULT NULL,
  `payment_id` int DEFAULT NULL,
  `order_amount` float DEFAULT NULL,
  `order_amount_withcurrency` float NOT NULL,
  `coupon_amount_withorder` float DEFAULT NULL,
  `order_amount_totalwith_currency` float DEFAULT NULL,
  `coupon_name` varchar(255) DEFAULT NULL,
  `coupon_price` float DEFAULT NULL,
  `curreny_code` varchar(20) DEFAULT NULL,
  `shipping_charge` float DEFAULT NULL,
  `shipping_charge_with_currency` float DEFAULT NULL,
  `shipping_url` varchar(255) DEFAULT NULL,
  `createdon` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedon` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `createdby` int DEFAULT NULL,
  `updatedby` int DEFAULT NULL,
  `viewed_details` tinyint NOT NULL DEFAULT '0' COMMENT '	0- for not viewed and 1-for viewed	',
  `tracking_number_status` tinyint NOT NULL DEFAULT '0' COMMENT '0-for not sent 1-for sent',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1-Pending Payment,2-Processing,3-Cancel Request,4-On Hold,5-Completed,\r\n6-Cancelled,7-Refunded,8-Failed',
  PRIMARY KEY (`order_id`)
) ENGINE=InnoDB AUTO_INCREMENT=760 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

