DROP TABLE IF EXISTS `tbl_product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tbl_product` (
  `pro_id` int NOT NULL AUTO_INCREMENT,
  `pro_title` text NOT NULL,
  `added_user_id` int NOT NULL DEFAULT '0',
  `updated_user_id` int NOT NULL DEFAULT '0',
  `pro_title_slug` text NOT NULL,
  `product_sku_name` varchar(255) DEFAULT NULL,
  `pro_reference_url` text,
  `pro_manufacturer_country_name` text,
  `pro_desc` text NOT NULL,
  `pro_brand` int DEFAULT NULL,
  `pro_shipping_charge` enum('1','0') DEFAULT '1',
  `pro_weight` float DEFAULT NULL,
  `pro_length` float DEFAULT NULL,
  `pro_width` float DEFAULT NULL,
  `pro_height` float DEFAULT NULL,
  `pro_price` float NOT NULL,
  `pro_offer_price` float NOT NULL,
  `pro_quantity` text NOT NULL,
  `pro_availability` enum('1','2','3') NOT NULL DEFAULT '1' COMMENT 'status 1=instock, 2=outof stock, 3= up coming',
  `pro_deleted` enum('1','2') NOT NULL DEFAULT '1' COMMENT '1 = not deleted, 2 = deleted',
  `pro_status` enum('1','2') NOT NULL DEFAULT '1' COMMENT 'status=1 enable status=2 disable',
  `pro_image` text,
  `product_image_feature1` text,
  `product_image_feature2` text,
  `product_image_feature3` text,
  `product_image_feature4` text,
  `product_image_feature5` text,
  `product_image_feature6` text,
  `product_video_name` text,
  `is_normal` enum('1','0') DEFAULT '0',
  `is_featured` enum('1','0') DEFAULT '0',
  `is_topseller` enum('1','0') DEFAULT '0',
  `is_special` enum('1','0') DEFAULT '0',
  `is_hot_sale` enum('1','0') DEFAULT '0',
  `is_recent` enum('1','0') DEFAULT '0',
  `is_toprated` enum('1','0') DEFAULT '0',
  `is_onsale` enum('1','0') DEFAULT '0',
  `is_best_rate` enum('1','0') DEFAULT '0',
  `pro_created_on` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`pro_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1784 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

